def next_prime_palindrome(n):
 def prime(x):
  if x<2:return False
  d=2
  while d*d<=x:
   if x%d==0:return False
   d+=1
  return True
 if 8<=n<=11:return 11
 length=len(str(n))
 while True:
  half=(length+1)//2
  for prefix in range(10**(half-1),10**half):
   text=str(prefix);candidate=int(text+text[-(2 if length%2 else 1)::-1])
   if candidate>=n and prime(candidate):return candidate
  length+=1

